
.bars {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 6px;
}

.b {
  display: flex;
  align-items: center;
  gap: 6px;
}

.lbl {
  flex: none;
  width: 30px;
  color: var(--sb-dim);
  font-size: 12px;
}

.hint {
  margin-top: 7px;
  font-size: 11px;
  border-top: 1px dashed var(--sb-line);
  padding-top: 5px;
}

.sb-tag-wrap {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.ctl {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
}

.cost {
  font-size: 10px;
  margin-top: 2px;
}

/* 招募人数沿用战报面板的深色输入风格，作用域留在本组件 */
.ipt.num {
  background: #0d0b08;
  border: 1px solid var(--sb-line);
  color: var(--sb-text);
  font-family: var(--sb-mono);
  font-size: 12px;
  padding: 2px 5px;
  width: 56px;
}

.ipt.num:focus {
  outline: none;
  border-color: var(--sb-song);
}

.fud {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.fud-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
