
.env-row {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.aura-list {
  display: grid;
  gap: 5px;
}

.units {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 6px;
}

.unit {
  border: 1px solid var(--sb-line);
  background: var(--sb-bg);
  padding: 5px 6px;
}

.unit.mine {
  border-left: 2px solid var(--sb-song);
}

.unit.foe {
  border-left: 2px solid var(--sb-life);
}

.uhead {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  margin-bottom: 4px;
  flex-wrap: wrap;
}

.st {
  margin-top: 3px;
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
}

.ctl {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.rules {
  margin-top: 7px;
  font-size: 11px;
  border-top: 1px dashed var(--sb-line);
  padding-top: 5px;
}

.logline {
  font-size: 12px;
  padding: 2px 0;
  border-bottom: 1px dotted var(--sb-line);
}

/* 表单与删除按钮沿用全局配色，仅补布局 */
.form {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
}

.ipt {
  background: #0d0b08;
  border: 1px solid var(--sb-line);
  color: var(--sb-text);
  font-family: var(--sb-font);
  font-size: 12px;
  padding: 2px 5px;
  min-width: 0;
  flex: 1 1 88px;
}

.ipt.num {
  flex: 0 0 70px;
}

.ipt.wide {
  flex: 1 1 160px;
}

.ipt:focus {
  outline: none;
  border-color: var(--sb-song);
}

.ctl .sb-btn.on {
  border-color: var(--sb-song);
  color: var(--sb-song);
}

.x {
  margin-left: auto;
  background: none;
  border: none;
  color: var(--sb-dim);
  cursor: pointer;
  font-size: 13px;
  line-height: 1;
  padding: 0 2px;
}

.x:hover {
  color: var(--sb-life);
}

.del-list {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 5px;
}

.fold summary {
  list-style: none;
}

.fold summary::-webkit-details-marker {
  display: none;
}

.fold summary::before {
  content: '\25B8';
  margin-right: 4px;
}

.fold[open] summary::before {
  content: '\25BE';
}
