
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 7px;
}

.c {
  border: 1px solid var(--sb-line);
  border-left: 2px solid var(--sb-song);
  background: var(--sb-bg);
  padding: 6px 7px;
}

.chead {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  margin-bottom: 4px;
}

.line {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 4px;
}

.lbl {
  flex: none;
  width: 28px;
  color: var(--sb-dim);
  font-size: 11px;
}

.v {
  flex: none;
  width: 26px;
  text-align: right;
  font-size: 11px;
}

.kv {
  display: flex;
  gap: 12px;
  font-size: 12px;
}

.kv .sb-dim {
  margin-right: 5px;
}

.sk {
  margin-top: 4px;
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
}

.warn {
  margin-top: 4px;
  font-size: 11px;
  color: var(--sb-life);
  border-top: 1px dashed var(--sb-line);
  padding-top: 3px;
}

/* 忠诚 ±5 与技能内联编辑：只补布局，配色沿用全局 */
.line .sb-btn {
  flex: none;
  padding: 0 5px;
  font-size: 11px;
}

.ipt {
  background: #0d0b08;
  border: 1px solid var(--sb-line);
  color: var(--sb-text);
  font-family: var(--sb-font);
  font-size: 12px;
  padding: 2px 5px;
  min-width: 0;
  flex: 1;
}

.ipt:focus {
  outline: none;
  border-color: var(--sb-song);
}
