
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
  gap: 7px;
}

.c {
  border: 1px solid var(--sb-line);
  border-left: 2px solid var(--sb-bond);
  background: var(--sb-bg);
  padding: 6px 7px;
  cursor: pointer;
}

.c.sel {
  border-color: var(--sb-bond);
  box-shadow: 0 0 6px rgba(201, 111, 138, 0.24) inset;
}

.chead {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  margin-bottom: 4px;
}

.line {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 3px;
}

.lbl {
  flex: none;
  width: 28px;
  color: var(--sb-dim);
  font-size: 11px;
}

.v {
  flex: none;
  width: 30px;
  text-align: right;
  font-size: 11px;
}

.line .sb-bar {
  flex: 1;
}

.mini {
  padding: 1px 6px;
  font-size: 11px;
  line-height: 1.3;
}

.act {
  border-color: var(--sb-bond);
  color: var(--sb-bond);
}

.rng {
  flex: none;
  font-size: 10px;
}

.imp {
  font-size: 11px;
  margin-top: 4px;
  border-top: 1px dotted var(--sb-line);
  padding-top: 3px;
}

.iv {
  margin-top: 3px;
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
}

.preg {
  margin-top: 4px;
  font-size: 11px;
  color: var(--sb-bond);
  border-top: 1px dashed var(--sb-line);
  padding-top: 3px;
}

.stage-row,
.imp-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}

.sb-in {
  flex: 1;
  min-width: 140px;
  background: #0d0b08;
  border: 1px solid var(--sb-line);
  color: var(--sb-text);
  font-family: var(--sb-font);
  font-size: 12px;
  padding: 3px 6px;
}

.kv {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 12px;
}

.kv .sb-dim {
  margin-right: 5px;
}

.hint {
  margin-top: 7px;
  font-size: 11px;
  border-top: 1px dashed var(--sb-line);
  padding-top: 5px;
}
