
.vols {
  display: grid;
  gap: 3px;
}

.vol {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--sb-dim);
  padding: 2px 0;
}

.vol .dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: 1px solid var(--sb-line);
  flex: none;
}

.vol.done .dot {
  background: var(--sb-dim);
}

.vol.done {
  color: var(--sb-text);
}

.vol.now {
  color: var(--sb-song);
}

.vol.now .dot {
  background: var(--sb-song);
  border-color: var(--sb-song);
}

.range {
  margin-left: auto;
  font-family: var(--sb-mono);
  font-size: 11px;
}

.hint {
  margin-top: 7px;
  font-size: 11px;
  border-top: 1px dashed var(--sb-line);
  padding-top: 5px;
}

.tag-wrap {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.dist {
  display: grid;
  gap: 4px;
  font-size: 12px;
}

.d {
  display: flex;
  gap: 6px;
  align-items: baseline;
}

/* 表单与行内删除按钮：沿用全局配色，仅补布局 */
.form {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
}

.ipt {
  background: #0d0b08;
  border: 1px solid var(--sb-line);
  color: var(--sb-text);
  font-family: var(--sb-font);
  font-size: 12px;
  padding: 2px 5px;
  min-width: 0;
  flex: 1 1 84px;
}

.ipt.wide {
  flex: 1 1 150px;
}

.ipt:focus {
  outline: none;
  border-color: var(--sb-song);
}

.x {
  margin-left: 4px;
  background: none;
  border: none;
  color: var(--sb-dim);
  cursor: pointer;
  font-size: 13px;
  line-height: 1;
  padding: 0 2px;
  vertical-align: middle;
}

.x:hover {
  color: var(--sb-life);
}

.fold summary {
  list-style: none;
}

.fold summary::-webkit-details-marker {
  display: none;
}

.fold summary::before {
  content: '\25B8';
  margin-right: 4px;
}

.fold[open] summary::before {
  content: '\25BE';
}
