
.sb-top {
  background: linear-gradient(180deg, #221c14, var(--sb-panel));
  border-bottom: 1px solid var(--sb-line);
  padding: 8px 10px;
}

.row1 {
  display: flex;
  align-items: center;
  gap: 8px;
}

.who {
  flex: 1;
  min-width: 0;
}

.name {
  font-size: 14px;
  font-weight: bold;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.sub {
  font-size: 11px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.clock {
  text-align: right;
  font-size: 11px;
  flex: none;
}

.row2 {
  display: flex;
  gap: 8px;
  margin-top: 7px;
}

.res {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
}

.res.narrow {
  flex: 0 0 92px;
}

.lbl {
  color: var(--sb-dim);
  font-size: 11px;
  flex: none;
}

.row3 {
  margin-top: 6px;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
}
