
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 7px;
}

.c {
  border: 1px solid var(--sb-line);
  border-left: 2px solid var(--sb-bond);
  background: var(--sb-bg);
  padding: 6px 7px;
}

.chead {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  margin-bottom: 5px;
}

.stage {
  display: flex;
  gap: 3px;
  margin-bottom: 5px;
}

.st {
  flex: 1;
  text-align: center;
  font-size: 10px;
  padding: 2px 0;
  border: 1px solid var(--sb-line);
  color: var(--sb-dim);
}

.st.on {
  border-color: var(--sb-bond);
  color: var(--sb-bond);
}

.st.now {
  background: rgba(201, 111, 138, 0.16);
}

.kv {
  display: flex;
  gap: 12px;
  font-size: 12px;
  flex-wrap: wrap;
  align-items: center;
}

.kv .sb-dim {
  margin-right: 5px;
}

.tnum {
  display: flex;
  align-items: center;
  gap: 4px;
}

.ctl {
  margin-top: 6px;
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.reg {
  margin-top: 5px;
  border-top: 1px dashed var(--sb-line);
  padding-top: 5px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  font-size: 11px;
}

.reg .sb-dim {
  grid-column: 1 / -1;
}

.tunes {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 7px;
}

.tune {
  border: 1px solid var(--sb-line);
  border-left: 2px solid var(--sb-bond);
  background: var(--sb-bg);
  padding: 5px 7px;
}

.tiers {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 7px;
}

.tier {
  border: 1px solid var(--sb-line);
  border-left: 2px solid var(--sb-void);
  background: var(--sb-bg);
  padding: 5px 7px;
}

.steps {
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
}

.step {
  flex: 1 1 auto;
  min-width: 52px;
  padding: 2px 5px;
  border: 1px solid var(--sb-line);
  background: var(--sb-panel);
  color: var(--sb-dim);
  font-size: 11px;
  text-align: center;
  white-space: nowrap;
}

.step.on {
  border-color: var(--sb-void);
  color: var(--sb-text);
}

.step.cur {
  background: var(--sb-void);
  border-color: var(--sb-void);
  color: var(--sb-bg);
  font-weight: 600;
}

.thead {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 3px;
}

.line {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 3px;
}

.lbl {
  flex: none;
  width: 30px;
  color: var(--sb-dim);
  font-size: 11px;
}

.line .sb-bar {
  flex: 1;
}

.v {
  flex: none;
  width: 30px;
  text-align: right;
  font-size: 11px;
}

.mini {
  padding: 1px 6px;
  font-size: 11px;
  line-height: 1.3;
}

.form {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-bottom: 7px;
}

.sb-in {
  background: #0d0b08;
  border: 1px solid var(--sb-line);
  color: var(--sb-text);
  font-family: var(--sb-font);
  font-size: 12px;
  padding: 3px 6px;
  min-width: 96px;
  flex: 1;
}

.sb-in.wide {
  flex: 2 1 200px;
}

.hint,
.rules {
  margin-top: 7px;
  font-size: 11px;
  border-top: 1px dashed var(--sb-line);
  padding-top: 5px;
}

// ── 房事底账 ──
.beds {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(420px, 1fr));
  gap: 7px;
}

.bed {
  border: 1px solid var(--sb-line);
  border-left: 2px solid var(--sb-life);
  background: var(--sb-bg);
  padding: 5px 7px;
}

.bed .thead b {
  color: var(--sb-life);
}

.parts {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 3px;
  margin: 4px 0;
}

.part {
  display: flex;
  align-items: center;
  gap: 4px;
}

.pname {
  flex: none;
  width: 62px;
  overflow: hidden;
  color: var(--sb-dim);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.part .sb-bar {
  flex: 1;
}

.part .sb-num {
  flex: none;
  width: 24px;
  color: var(--sb-dim);
  font-size: 11px;
  text-align: right;
}

.删癖 {
  margin-left: 3px;
  cursor: pointer;
  opacity: 0.7;
}

.删癖:hover {
  opacity: 1;
  color: var(--sb-life);
}
