
.tree-pick {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.tree-pick .sb-btn.on {
  border-color: var(--sb-song);
  color: var(--sb-song);
}

.tier-wrap {
  margin-bottom: 7px;
}

.tier-head {
  font-size: 12px;
  color: var(--sb-dim);
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 3px;
}

.tier-head.reached {
  color: var(--sb-song);
}

.nodes {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

/* 节点与它的 +5 按钮成组，避免换行时脱开 */
.node-cell {
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.node-cell .sb-node {
  font-family: var(--sb-font);
  cursor: pointer;
}

.node-cell .sb-node:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.mini {
  font-size: 10px;
  padding: 1px 4px;
}

.lv {
  font-size: 10px;
  margin-left: 3px;
}

.ctl {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
}

.cost {
  font-size: 10px;
  margin-top: 2px;
}

.extra {
  margin-top: 6px;
}

.hint {
  margin-top: 7px;
  font-size: 11px;
  border-top: 1px dashed var(--sb-line);
  padding-top: 5px;
}

.tech-chain {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
}

.arrow {
  color: var(--sb-dim);
  font-size: 10px;
}

/* 表单沿用战报面板的深色输入风格，但作用域留在本组件 */
.form {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.ipt {
  background: #0d0b08;
  border: 1px solid var(--sb-line);
  color: var(--sb-text);
  font-family: var(--sb-font);
  font-size: 12px;
  padding: 2px 5px;
  min-width: 0;
  flex: 1 1 92px;
}

.ipt.wide {
  flex: 1 1 150px;
}

.ipt.sel {
  flex: 0 0 84px;
}

/* 节点里的层级下拉要能塞进 .nodes 的流式布局，所以比表单里的更窄 */
.ipt.sel.mini {
  flex: 0 0 auto;
  width: 62px;
  padding: 1px 2px;
}

.ipt:focus {
  outline: none;
  border-color: var(--sb-song);
}
