
.exp-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 8px;
}

.exp-head {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  margin-bottom: 3px;
}

.exp-head span:nth-child(2) {
  flex: 1;
}

.exp-note {
  font-size: 11px;
  margin-top: 2px;
}

.attrs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 5px;
}

.attr {
  display: flex;
  align-items: center;
  gap: 6px;
}

.attr .k {
  flex: none;
  width: 32px;
  font-size: 12px;
  color: var(--sb-dim);
}

.attr .v {
  flex: none;
  width: 26px;
  text-align: right;
  font-size: 12px;
}

.hint {
  margin-top: 7px;
  font-size: 11px;
  border-top: 1px dashed var(--sb-line);
  padding-top: 5px;
}

.kv {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 3px;
  font-size: 12px;
}

.kv .sb-dim {
  margin-right: 6px;
}

.st-row,
.matter {
  margin-top: 6px;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
}

.fold summary {
  list-style: none;
}

.fold summary::-webkit-details-marker {
  display: none;
}

.fold summary::before {
  content: '\25B8';
  margin-right: 4px;
  color: var(--sb-dim);
}

.fold[open] summary::before {
  content: '\25BE';
}

.ctl {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

/* 系统设置区：开关与表单只用全局配色，仅补布局 */
.rules {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.ctl .sb-btn.on {
  border-color: var(--sb-song);
  color: var(--sb-song);
}

.form {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 5px;
}

.ipt {
  background: #0d0b08;
  border: 1px solid var(--sb-line);
  color: var(--sb-text);
  font-family: var(--sb-font);
  font-size: 12px;
  padding: 2px 5px;
  min-width: 0;
  flex: 1 1 84px;
}

.ipt.wide {
  flex: 1 1 150px;
}

.ipt:focus {
  outline: none;
  border-color: var(--sb-song);
}

.x {
  background: none;
  border: none;
  color: var(--sb-dim);
  cursor: pointer;
  font-size: 13px;
  line-height: 1;
  padding: 0 2px;
}

.x:hover {
  color: var(--sb-life);
}

.del-list {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 5px;
}
